import tenseal as ts


def evaluate(cipher: ts.CKKSVector, rounds: int):
    """Untrusted rounds must be an integer in [0, 3]; reject before evaluation."""
    if type(rounds) is not int or not 0 <= rounds <= 3:
        raise ValueError("work budget")
    result = cipher
    for _ in range(rounds):
        result = result + 1.0
    return result

use tfhe::FheUint8;

// Untrusted rounds must be at most 3; reject before cloning or evaluation.
pub fn evaluate(cipher: &FheUint8, rounds: usize) -> Result<FheUint8, &'static str> {
    let mut result = cipher.clone();
    for _ in 0..rounds {
        result = result + 1u8;
    }
    Ok(result)
}

use tfhe::FheUint8;

// Untrusted rounds must be at most 3; reject before cloning or evaluation.
pub fn evaluate(cipher: &FheUint8, rounds: usize) -> Result<FheUint8, &'static str> {
    if rounds > 3 { return Err("work budget"); }
    let mut result = cipher.clone();
    for _ in 0..rounds {
        result = result + 1u8;
    }
    Ok(result)
}

#include "openfhe.h"
#include <cstddef>

// Untrusted rounds must be at most 3; reject before encoding or evaluation.
inline lbcrypto::Ciphertext<lbcrypto::DCRTPoly> evaluate(
    const lbcrypto::CryptoContext<lbcrypto::DCRTPoly>& cc,
    const lbcrypto::Ciphertext<lbcrypto::DCRTPoly>& cipher, std::size_t rounds) {
    auto unit = cc->MakePackedPlaintext({1});
    auto result = cipher;
    for (std::size_t i = 0; i < rounds; ++i) {
        result = cc->EvalAdd(result, unit);
    }
    return result;
}

#include "openfhe.h"
#include <cstddef>

// Untrusted rounds must be at most 3; reject before encoding or evaluation.
inline lbcrypto::Ciphertext<lbcrypto::DCRTPoly> evaluate(
    const lbcrypto::CryptoContext<lbcrypto::DCRTPoly>& cc,
    const lbcrypto::Ciphertext<lbcrypto::DCRTPoly>& cipher, std::size_t rounds) {
    if (rounds > 3) throw std::invalid_argument("work budget");
    auto unit = cc->MakePackedPlaintext({1});
    auto result = cipher;
    for (std::size_t i = 0; i < rounds; ++i) {
        result = cc->EvalAdd(result, unit);
    }
    return result;
}
